"""In-process content signatures for registered resources.

Each resource keeps at most one signature record naming the signer, the
HMAC algorithm, the key id, the hexadecimal signature value and the
signed digest. Text is kept verbatim while hexadecimal values are
normalized to lowercase. Nothing here is persisted: stopping or
restarting the service clears every record.
"""

from __future__ import annotations

import hashlib
import hmac
import re
from dataclasses import dataclass

#: A digest is exactly 64 hexadecimal characters; mixed case is accepted
#: but the digest is always stored in lowercase.
_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{64}")

#: Text fields are non-empty and bounded by 256 Unicode code points.
MAX_TEXT_LENGTH = 256

#: The two supported HMAC algorithms and their hexadecimal output lengths.
ALGORITHMS: tuple[str, ...] = ("hmac-sha256", "hmac-sha512")
_ALGORITHM_HASHES = {
    "hmac-sha256": hashlib.sha256,
    "hmac-sha512": hashlib.sha512,
}
_HEX_LENGTHS = {"hmac-sha256": 64, "hmac-sha512": 128}
_HEX_PATTERNS = {
    algorithm: re.compile(r"[0-9a-fA-F]{%d}" % length)
    for algorithm, length in _HEX_LENGTHS.items()
}

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset(
    {"signer", "algorithm", "key_id", "signature", "digest"}
)
_REQUIRED_FIELDS = ("signer", "algorithm", "key_id", "signature", "digest")


class SignatureValidationError(ValueError):
    """A signature payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class SignatureError(ValueError):
    """A signature operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class SignatureRecord:
    """The single content signature record stored for a resource."""

    signer: str
    algorithm: str
    key_id: str
    signature: str
    digest: str

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {
            "id": resource_id,
            "signer": self.signer,
            "algorithm": self.algorithm,
            "key_id": self.key_id,
            "signature": self.signature,
            "digest": self.digest,
        }


def _required_text(value: object, label: str) -> str:
    """Validate a required non-empty string of at most 256 code points."""

    if not isinstance(value, str):
        raise SignatureValidationError(f"{label} must be a string.")
    if not value:
        raise SignatureValidationError(f"{label} must not be empty.")
    if len(value) > MAX_TEXT_LENGTH:
        raise SignatureValidationError(
            f"{label} must not exceed {MAX_TEXT_LENGTH} Unicode code points."
        )
    return value


def _require_digest(value: object) -> str:
    if not isinstance(value, str) or _DIGEST_PATTERN.fullmatch(value) is None:
        raise SignatureValidationError(
            "Field 'digest' must be a 64-character hexadecimal string."
        )
    return value.lower()


def build_signature_fields(
    payload: object,
) -> tuple[str, str, str, str, str]:
    """Validate a decoded signature payload and return normalized values.

    Returns ``(signer, algorithm, key_id, signature, digest)``. The digest
    and signature hexadecimal values are normalized to lowercase; the
    signature length must match its algorithm (64 characters for
    HMAC-SHA256 and 128 for HMAC-SHA512).
    """

    if not isinstance(payload, dict):
        raise SignatureValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise SignatureValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise SignatureValidationError(
                f"Missing required field: {field!r}."
            )

    signer = _required_text(payload["signer"], "Field 'signer'")

    algorithm = payload["algorithm"]
    if not isinstance(algorithm, str) or algorithm not in _ALGORITHM_HASHES:
        allowed = ", ".join(ALGORITHMS)
        raise SignatureValidationError(
            f"Field 'algorithm' must be one of: {allowed} (case-sensitive)."
        )

    key_id = _required_text(payload["key_id"], "Field 'key_id'")

    raw_signature = payload["signature"]
    if (
        not isinstance(raw_signature, str)
        or _HEX_PATTERNS[algorithm].fullmatch(raw_signature) is None
    ):
        expected_length = _HEX_LENGTHS[algorithm]
        raise SignatureValidationError(
            f"Field 'signature' must be a {expected_length}-character "
            "hexadecimal string matching its algorithm."
        )
    signature = raw_signature.lower()

    digest = _require_digest(payload["digest"])

    return signer, algorithm, key_id, signature, digest


def compute_signature(algorithm: str, key_id: str, digest: str) -> str:
    """Recompute the lowercase hexadecimal HMAC for a stored record.

    The key is the UTF-8 byte sequence of ``key_id`` and the signed message
    is the lowercase hexadecimal digest text.
    """

    return hmac.new(
        key_id.encode("utf-8"),
        digest.encode("ascii"),
        _ALGORITHM_HASHES[algorithm],
    ).hexdigest()


class SignatureStore:
    """Process-local storage of at most one signature record per resource."""

    def __init__(self) -> None:
        self._records: dict[str, SignatureRecord] = {}

    def reset(self) -> None:
        self._records = {}

    def remove_resource(self, resource_id: str) -> None:
        """Remove any signature record for a resource.

        An unknown id is a no-op.
        """

        self._records.pop(resource_id, None)

    def add(
        self, resource_id: str, payload: object
    ) -> tuple[SignatureRecord, bool]:
        """Validate and record the signature for ``resource_id``.

        Returns ``(record, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent repeat
        of the exact same normalized content (HTTP 200).

        Raises :class:`SignatureValidationError` for an invalid payload or
        :class:`SignatureError` with code ``signature_conflict`` when a
        different record is already stored; the stored record is never
        overwritten.
        """

        signer, algorithm, key_id, signature, digest = (
            build_signature_fields(payload)
        )
        record = SignatureRecord(
            signer=signer,
            algorithm=algorithm,
            key_id=key_id,
            signature=signature,
            digest=digest,
        )

        existing = self._records.get(resource_id)
        if existing is not None:
            if existing == record:
                return existing, False
            raise SignatureError(
                "signature_conflict",
                "A different signature record is already registered for "
                "this resource.",
            )

        self._records[resource_id] = record
        return record, True

    def get(self, resource_id: str) -> SignatureRecord | None:
        return self._records.get(resource_id)

def _parse_signatures_summary_query(
    query_string: str,
) -> tuple[str | None, str | None]:
    """Parse the optional, single ``signer`` query parameter.

    Returns ``(signer, None)`` -- with ``None`` when the parameter is
    absent -- or ``(None, message)`` for an unknown parameter, a repeated
    ``signer`` or an empty value. The value is matched verbatim against
    the recorded signer: case-sensitive, no trimming, no folding.
    """

    pairs = parse_qsl(
        query_string, keep_blank_values=True, strict_parsing=False
    )
    signer: str | None = None
    for key, value in pairs:
        if key != "signer":
            return None, f"Unknown query parameter: {key!r}."
        if signer is not None:
            return None, "Query parameter 'signer' must not be repeated."
        if value == "":
            return None, "Query parameter 'signer' must not be empty."
        signer = value
    return signer, None


def _handle_signatures_summary(
    method: str,
    environ: dict[str, Any],
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    # The summary is read-only: a declared non-empty (or malformed) body is
    # a bad request without consulting any business data. An omitted header
    # and an explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # Only the optional ``signer`` filter is accepted; unknown or repeated
    # parameters and an empty value are rejected before any data is read.
    signer, query_error = _parse_signatures_summary_query(
        str(environ.get("QUERY_STRING", ""))
    )
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Computed on the fly from the current stores: entries unfold in
    # resource registration order and are never reordered; each resource
    # carries at most one signature record, and resources without one are
    # skipped silently. Each entry puts the owning resource id first,
    # followed by the per-resource query response fields in their response
    # order. Nothing is recorded and no state is touched; a filter without
    # a hit is an ordinary empty array.
    records: list[dict[str, object]] = []
    for resource in store.list_all():
        record = signature_store.get(resource.id)
        if record is None:
            continue
        if signer is not None and record.signer != signer:
            continue
        records.append(
            {
                "resource_id": resource.id,
                "signer": record.signer,
                "algorithm": record.algorithm,
                "key_id": record.key_id,
                "signature": record.signature,
                "digest": record.digest,
            }
        )
    return _json_response(
        start_response,
        "200 OK",
        records,
        trailing_newline=True,
    )


def _handle_signatures_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    # Validate the whole body before touching any store, so a bad request
    # can never leave a partial signature.
    try:
        build_signature_fields(payload)
    except SignatureValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        record, created = signature_store.add(raw_id, payload)
    except SignatureError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    return _json_response(
        start_response,
        "201 Created" if created else "200 OK",
        record.to_dict(raw_id),
        trailing_newline=True,
    )


def _handle_signatures_get(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    record = signature_store.get(raw_id)
    if record is None:
        return _error(
            start_response,
            "404 Not Found",
            "signature_not_found",
            "No content signature is registered for this resource.",
        )

    return _json_response(
        start_response,
        "200 OK",
        record.to_dict(raw_id),
        trailing_newline=True,
    )


def _handle_signatures(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "POST":
        return _handle_signatures_post(environ, raw_id, start_response)
    if method == "GET":
        return _handle_signatures_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_signature_verify(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Read-only: verification takes no request body and derives every input
    # from the stored record, so it never reads the request stream.
    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    registered = signature_store.get(raw_id)
    if registered is None:
        return _error(
            start_response,
            "404 Not Found",
            "signature_not_found",
            "No content signature is registered for this resource.",
        )

    # The signed digest must be the resource's registered digest.
    if registered.digest != resource.digest:
        return _error(
            start_response,
            "409 Conflict",
            "signed_digest_mismatch",
            "The signature digest does not match the resource digest.",
        )

    # Recompute the HMAC from the stored fields and compare it with the
    # registered signature value; nothing about this check is recorded.
    expected = compute_signature(
        registered.algorithm, registered.key_id, registered.digest
    )
    valid = hmac.compare_digest(expected, registered.signature)
    return _json_response(
        start_response,
        "200 OK",
        {"id": raw_id, "valid": valid},
        trailing_newline=True,
    )


