    # The summary is read-only: a declared non-empty (or malformed) body is
    # a bad request without consulting any business data. An omitted header
    # and an explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # No filtering or pagination parameters whatsoever are accepted.
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Computed on the fly from the current stores: one entry per registered
    # resource in resource registration order, never reordered, each with
    # the six keys id, signer, algorithm, key_id, valid and reason in this
    # order. A resource without a signature still contributes its entry
    # with null signature fields, ``valid`` false and reason
    # ``signature_not_found``; a record whose signed digest no longer
    # matches the resource digest reports ``signed_digest_mismatch`` as a
    # false conclusion without failing the whole summary; every other
    # record is reverified with the per-resource verification rules and
    # reports a null reason. Nothing is recorded and no state is touched.
    results: list[dict[str, object]] = []
    for resource in store.list_all():
        record = signature_store.get(resource.id)
        if record is None:
            results.append(
                {
                    "id": resource.id,
                    "signer": None,
                    "algorithm": None,
                    "key_id": None,
                    "valid": False,
                    "reason": "signature_not_found",
                }
            )
            continue
        if record.digest != resource.digest:
            results.append(
                {
                    "id": resource.id,
                    "signer": record.signer,
                    "algorithm": record.algorithm,
                    "key_id": record.key_id,
                    "valid": False,
                    "reason": "signed_digest_mismatch",
                }
            )
            continue
        expected = compute_signature(
            record.algorithm, record.key_id, record.digest
        )
        results.append(
            {
                "id": resource.id,
                "signer": record.signer,
                "algorithm": record.algorithm,
                "key_id": record.key_id,
                "valid": hmac.compare_digest(expected, record.signature),
                "reason": None,
            }
        )
    return _json_response(
        start_response,
        "200 OK",
        results,
        trailing_newline=True,
    )


